//   heads[skin].mask = R peso de piel, G peso de pelo, B peso de cejas/bigote (para teñir piel y pelo sin perder el dibujo)
//   info[skin]       = color de pelo y cejas del original, centro y tamaño de los ojos, centro de la boca (coordenadas 1024)
//   erase            = tira con la máscara de ojos y boca de cada skin (rectángulo de la cara) para dibujar los gestos
//   body             = R sombreado de la ropa (200 = 1), G capellada clara de las zapatillas (de la remera del
//                      survivor-male sin manchas, el pantalón y los zapatos del male)
